pub fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    let mut chars = txt.chars();

    // Non-empty check
    let last = match chars.next_back() {
        Some(c) => c,
        None => return false,
    };

    // Last char must be an ASCII letter
    if !last.is_ascii_alphabetic() {
        return false;
    }

    // Either single-character string, or preceding char is a space
    match chars.next_back() {
        None => true,
        Some(prev) => prev == ' ',
    }
}